public enum AirEraseReceipt: Equatable, Hashable {

    case completed(erasedBytes: UInt64, erasedChunks: UInt64, timeElapsedMs: UInt64
    )
    case incomplete(keyCleanupFailed: Bool, hostCleanupFailed: Bool
    )





}

#if compiler(>=6)
extension AirEraseReceipt: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAirEraseReceipt: FfiConverterRustBuffer {
    typealias SwiftType = AirEraseReceipt

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AirEraseReceipt {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        case 1: return .completed(erasedBytes: try FfiConverterUInt64.read(from: &buf), erasedChunks: try FfiConverterUInt64.read(from: &buf), timeElapsedMs: try FfiConverterUInt64.read(from: &buf)
        )

        case 2: return .incomplete(keyCleanupFailed: try FfiConverterBool.read(from: &buf), hostCleanupFailed: try FfiConverterBool.read(from: &buf)
        )

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AirEraseReceipt, into buf: inout [UInt8]) {
        switch value {


        case let .completed(erasedBytes,erasedChunks,timeElapsedMs):
            writeInt(&buf, Int32(1))
            FfiConverterUInt64.write(erasedBytes, into: &buf)
            FfiConverterUInt64.write(erasedChunks, into: &buf)
            FfiConverterUInt64.write(timeElapsedMs, into: &buf)


        case let .incomplete(keyCleanupFailed,hostCleanupFailed):
            writeInt(&buf, Int32(2))
            FfiConverterBool.write(keyCleanupFailed, into: &buf)
            FfiConverterBool.write(hostCleanupFailed, into: &buf)

        }
    }
}


